   374→function shouldAskBudget(query: UserQuery): boolean {
   375→  // Only ask budget for high-value occasions or if user seems budget-conscious
   376→  const lowerMessage = query.message.toLowerCase();
   377→
   378→  const budgetSensitiveKeywords = [
   379→    'ถูก',
   380→    'ประหยัด',
   381→    'ราคาดี',
   382→    'cheap',
   383→    'affordable',
   384→    'budget',
   385→    'save',
   386→    'ไม่แพง',
   387→  ];
   388→
   389→  const highValueOccasions = ['wedding', 'งานแต่ง', 'work', 'ทำงาน', 'dinner', 'ดินเนอร์'];
   390→
   391→  const isBudgetSensitive = budgetSensitiveKeywords.some((keyword) => lowerMessage.includes(keyword));
   392→  const isHighValueOccasion = highValueOccasions.some((occasion) => lowerMessage.includes(occasion));
   393→
   394→  return isBudgetSensitive || isHighValueOccasion;
   395→}
   396→
   397→/**
   398→ * Formats clarification questions for AI response
   399→ *
   400→ * @param clarifications - Array of clarifications needed
   401→ * @returns Formatted string for AI to use
   402→ */
   403→export function formatClarificationQuestions(clarifications: ClarificationNeeded[]): string {
   404→  if (clarifications.length === 0) {
   405→    return '';
   406→  }
   407→
   408→  // Ask only the highest priority question (first one)
   409→  const topClarification = clarifications[0];
   410→
   411→  return topClarification.question;
   412→}
   413→
   414→/**
   415→ * Checks if user message is answering a clarification question
   416→ *
   417→ * @param message - User's message
   418→ * @param previousClarificationType - Type of clarification asked previously
   419→ * @returns True if answering clarification
   420→ */
   421→export function isAnsweringClarification(
   422→  message: string,
   423→  previousClarificationType?: string
   424→): boolean {
   425→  if (!previousClarificationType) {
   426→    return false;
   427→  }
   428→
   429→  switch (previousClarificationType) {
   430→    case 'gender':
   431→      return detectGender(message) !== undefined;
   432→
   433→    case 'occasion':
   434→      return detectOccasion(message) !== undefined;
   435→
   436→    case 'destination':
   437→      return detectDestination(message) !== undefined;
   438→
   439→    case 'budget':
   440→      return detectBudget(message) !== undefined;
   441→
   442→    default:
   443→      return false;
   444→  }
   445→}
   446→
   447→/**
   448→ * Export all utilities
   449→ */
   450→export default {
   451→  analyzeUserQuery,
   452→  detectGender,
   453→  detectOccasion,
   454→  detectBudget,
   455→  detectDestination,
   456→  isTravelQuery,
   457→  isOccasionVague,
   458→  getClarificationsNeeded,
   459→  formatClarificationQuestions,
   460→  isAnsweringClarification,
   461→};
