    ],
  },
  style_change: {
    thai: [
      'สไตล์อื่น',
      'formal กว่า',
      'casual กว่า',
      'ทางการกว่า',
      'สบายๆ กว่า',
      'เท่กว่า',
      'น่ารักกว่า',
      'เซ็กซี่กว่า',
